const WORKSHEETS=[];
Object.entries(TOPICS).forEach(([k,t])=>{
  const n=t.questions.length,sets=Math.max(1,Math.round(n/10));
  for(let s=0;s<sets;s++){
    const qs=[];for(let i=s;i<n;i+=sets)qs.push(i);
    WORKSHEETS.push({title:t.name+(sets>1?` — Set ${s+1}`:''),topic:k,diff:'Mixed',qs});
  }
});

